mapper.sql:
SELECT id, name, ruleText, startTime, endTime, totalStock, grantAmount, status, configVersion
FROM quota_activity
WHERE id = #{id}

mapper.update:
UPDATE quota_activity
SET status = 'published', configVersion = configVersion + 1
WHERE id = #{id}

UPDATE quota_activity
SET name = #{name}, ruleText = #{ruleText}, configVersion = configVersion + 1
WHERE id = #{id}

mapper.select:
SELECT userId, claimNo
FROM quota_claim
WHERE activityId = #{id}
